{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C03", "C08", "C33", "C64", "C100"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C03", "C08", "C33", "C64", "C100"],
  "claims": [
    {
      "claim": "AZD0837, the closest structural context sharing the benzyl amidoxime–azetidine amide core, has measured absolute oral bioavailability of 22–55% in humans (C03, C08, C33, C64); all reported values are at or above the 20% threshold.",
      "card_ids": ["C03", "C08", "C33", "C64"]
    },
    {
      "claim": "New L3 oral exposure data for AZD0837 in pigs show measurable systemic exposure after enteral dosing (control AUC0-6h 40.4 µmol·h/L; with ketoconazole 74.4 µmol·h/L, ratio 1.99), confirming oral absorption and indicating first-pass/efflux involvement; this does not contradict F ≥ 20%.",
      "card_ids": ["C100"]
    },
    {
      "claim": "The ester prodrug motif is not itself a barrier to F ≥ 20%, as the ethyl ester prodrug perindopril has high parent oral bioavailability (~65–75%) in humans.",
      "card_ids": ["C10", "C17", "C18"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C100"]
    }
  ],
  "evidence_gaps": [
    "No direct measured oral bioavailability for the exact query molecule.",
    "AZD0837 differs from the query in the amidoxime O-substituent (methoxy vs hydroxy) and in the acyl/ester region, so the transfer is analog-based rather than identical-molecule evidence.",
    "C100 is pig enteral data with ketoconazole coadministration and no IV comparator, so it cannot quantify absolute bioavailability.",
    "No query-specific data on first-pass metabolism, efflux, solubility, or prodrug conversion are available.",
    "The lower end of the AZD0837 F range (22%) is close to the 20% threshold.",
    "Most other L3 records concern unrelated molecules and were not used in the decision."
  ],
  "decision_summary": "Prediction remains high (F ≥ 20%): the closest structural context, AZD0837, has measured absolute oral bioavailability of 22–55% in humans, and new L3 oral exposure data in pigs show measurable systemic exposure after enteral dosing, supporting oral absorption without contradicting the threshold. Confidence stays moderate because the evidence is analog-based and the lower bound is near the threshold."
}

